@font-face {
    font-family: "FrameworkIcons";
    src: url("data:font/woff2;base64,") format("woff2");
    font-weight: normal;
    font-style: normal;
}

.f-icon-i {
    font-family: "FrameworkIcons" !important;
    font-size: 16px;
}

.f-icon {
    font-family: "FrameworkIcons" !important;
    width: fit-content;
    height: fit-content;
    margin: auto;

    &::before {
        content: attr(data-icon);
        font-size: 18px;
    }
}

body {
    padding: 2px;
    margin: 0;
    font-family: var(--vscode-font-family);
    color: var(--vscode-foreground);
    background-color: var(--vscode-editor-background);
    max-width: 550px;
    transition: opacity ease 0.1s;

    &::before {
        content: "css ✓";
        position: fixed;
        bottom: 6px;
        right: 4px;
        background-color: var(--vscode-editor-background);
        color: var(--vscode-descriptionForeground);
        padding: 2px 6px;
        border-radius: 3px;
        font-size: 9px;
        font-family: var(--vscode-font-family);
    }
}

/* ── layout ──────────────────────────────────── */

.grid {
    display: flex;
    flex-wrap: wrap;
    gap: 6px;
    align-items: flex-start;
}

.card {
    background-color: var(--vscode-editorWidget-background);
    border: 1px solid var(--vscode-panel-border);
    border-radius: 3px;
    padding: 6px 7px 5px;
    min-width: 130px;
}

.card-full {
    flex: 1 1 100%;
}

.card-row {
    display: flex;
    gap: 6px;
    flex: 1 1 100%;
    align-items: flex-start;
}

.card-row>.card {
    flex: 1;
    min-width: 0;
}

.card-title {
    font-size: 9px;
    text-transform: uppercase;
    letter-spacing: 0.8px;
    color: var(--vscode-descriptionForeground);
    margin-bottom: 4px;
}

.btn-row {
    display: flex;
    flex-wrap: wrap;
    gap: 3px;
}

/* ── controls ────────────────────────────────── */

.btn {
    display: flex;
    width: 100%;
    padding: 4px 6px;
    margin-bottom: 3px;
    background-color: var(--vscode-button-background);
    color: var(--vscode-button-foreground);
    border: none;
    border-radius: 2px;
    cursor: pointer;
    font-size: 11px;
    text-align: left;
    font-family: var(--vscode-editor-font-family, monospace);
    transition: opacity 0.1s;
    white-space: nowrap;
    flex-wrap: wrap;
    gap: 2px;

    >:first-child {
        margin-right: auto;
        /* margin-left: auto; */
    }
}

.btn.compact {
    width: fit-content;
}

.btn:last-child {
    margin-bottom: 0;
}

.btn-row .btn {
    width: auto;
    margin-bottom: 0;
}

.btn:hover {
    background-color: var(--vscode-button-hoverBackground);
}

.btn:active {
    opacity: 0.7;
}

.btn.type-only {
    background-color: var(--vscode-button-secondaryBackground);
    color: var(--vscode-button-secondaryForeground);
}

.btn.type-only:hover {
    background-color: var(--vscode-button-secondaryHoverBackground);
}

.btn.the-chosen-one {
    box-shadow: inset 0 0 0 1px #2ecc71;
    background-color: rgba(46, 204, 113, 0.25);
}

.input-row {
    display: flex;
    gap: 4px;
    align-items: center;
    margin-bottom: 5px;
}

.input-row .branch-input {
    flex: 1;
    margin-bottom: 0;
}

.btn-save-hidden {
    visibility: hidden;
}

.btn-save {
    flex-shrink: 0;
    display: flex;
    align-items: center;
    justify-content: center;
    padding: 3px 4px;
    background: none;
    border: 1px solid var(--vscode-panel-border);
    border-radius: 2px;
    color: var(--vscode-descriptionForeground);
    cursor: pointer;
    line-height: 1;
    transition: all 0.1s;
}

.btn-save svg {
    width: 14px;
    height: 14px;
    fill: currentColor;
    display: block;
}

.btn-save:hover {
    background-color: var(--vscode-button-background);
    color: var(--vscode-button-foreground);
    border-color: var(--vscode-button-background);
}

.btn-save.saved {
    color: var(--vscode-successIcon-foreground);
    border-color: var(--vscode-successIcon-foreground);
}

.branch-input {
    display: block;
    width: 100%;
    box-sizing: border-box;
    padding: 4px 8px;
    margin-bottom: 5px;
    background-color: var(--vscode-input-background);
    color: var(--vscode-input-foreground);
    border: 1px solid var(--vscode-input-border, transparent);
    border-radius: 2px;
    font-size: 11px;
    font-family: var(--vscode-editor-font-family, monospace);
    outline: none;
}

.branch-input:focus {
    border-color: var(--vscode-focusBorder);
}

/* ── debug badge ─────────────────────────────── */

.js-running-check-ok {
    position: fixed;
    bottom: 6px;
    right: 35px;
    background-color: var(--vscode-editor-background);
    color: var(--vscode-descriptionForeground);
    padding: 2px 6px;
    border-radius: 3px;
    font-size: 9px;
    font-family: var(--vscode-font-family);
}

.hidden-inline-icons {
    display: none !important;
}

.more-info {
    font-size: 10px;
    /* margin-right: auto; */
}

/* ── language toolbar ─────────────────────────── */

.toolbar {
    display: flex;
    align-items: flex-end;
    gap: 6px;
    margin-bottom: 6px;
    position: fixed;
    bottom: -1px;
    left: 7px;
    justify-content: flex-start;

    &:hover {}
}

#reset-hard-push-btn {
    background: rgba(255, 0, 0, 0.06);

    &:hover {
        background: rgba(255, 0, 0, 0.2);
    }
}

#cherry-pick-btn {
    background: rgba(60, 255, 0, 0.06);

    &:hover {
        background: rgba(72, 255, 0, 0.2);
    }
}

.more-info[data-i18n] {
    &::before {
        content: '(';
    }

    &::after {
        content: ')';
    }
}

[hidden] {
    display: none;
}

.grid3 {
    display: grid;
    justify-content: space-evenly;
    grid-template-columns: 1fr 1fr 1fr;
    padding-top: 20px;
    gap: 0px 5px;
    align-items: start;

    .card-title {
        position: absolute;
        top: 8px;
    }
}

.grid3_05_05_1 {
    display: grid;
    grid-template-columns: 0.5fr 0.5fr 1fr;
}

/* #region custom dropdown */

.custom-dropdown-container {
    font-family: var(--vscode-font-family);
    color: var(--vscode-descriptionForeground);
    /* display: inline-block; */
    display: flex;
    /* min-width: 160px; */
    position: relative;
    --height-btns: 44px;

    &.has-left-icon {
        display: flex;
        align-items: center;
        gap: 4px;

        .custom-dropdown {
            flex: 1;
        }

        .custom-dropdown-selected {
            padding-left: 25px;
        }
    }

    .cdc-icon-left {
        flex: none;
        position: absolute;
        z-index: 1;
        margin-left: 8px;
    }

    .custom-dropdown-option-image {
        max-width: 100px;
        max-height: 70px;
    }

    .cdc-arrow-open {
        position: absolute;
        right: 5px;
        top: 0;
        bottom: 0;
        margin: auto;
        height: fit-content;
        z-index: 32541341;
        pointer-events: none;
    }

    .custom-dropdown {
        position: relative;
        border-radius: 4px;
        cursor: pointer;
        user-select: none;
        /* min-width: 160px; */
        /* font-size: min(3.2vh, 18px); */

        .cm-dn-buttons {
            height: var(--height-btns);
            position: absolute;
            top: 100%;
            left: 0;
            display: flex;
            flex-direction: row;
            width: 100%;
            justify-content: space-around;
            border: 1px solid var(--vscode-dropdown-border, var(--vscode-panel-border));
            border-top: none;
            border-bottom: unset;
            background: var(--vscode-dropdown-background, var(--vscode-input-background));
            box-sizing: border-box;

            >div {
                width: 49%;
                height: var(--height-btns);
                display: flex;
                align-items: center;
                justify-content: center;
                cursor: pointer;
            }
        }
    }

    .custom-dropdown:has(>.cm-dn-buttons) {
        .custom-dropdown-options {
            top: calc(100% + var(--height-btns));
        }
    }


    .custom-dropdown-selected.cddown-selected-not-stealth {
        background-color: var(--vscode-input-background);
        height: 24px;
    }

    .custom-dropdown-selected {
        padding: 1px;
        border-radius: 4px;
        text-align: center;
        padding-right: 27px;
        padding-left: 9px;
        height: 90%;
        display: flex;
        align-items: center;

        &:hover {
            background-color: var(--vscode-list-hoverBackground);
        }
    }

    .custom-dropdown-selected.dd-visible-top {
        border-radius: 2px;
        border-end-end-radius: 4px;
        border-end-start-radius: 4px;
        outline: 1px solid var(--vscode-focusBorder);
    }

    .custom-dropdown-options {
        position: absolute;
        width: 100%;
        top: 100%;
        left: 0;
        background: var(--vscode-dropdown-background, var(--vscode-input-background));
        border: 1px solid var(--vscode-dropdown-border, var(--vscode-panel-border));
        border-top: none;
        z-index: 100;
        max-height: 210px;
        overflow-y: auto;
        box-sizing: border-box;
        border-top: 1px solid var(--vscode-dropdown-border, var(--vscode-panel-border));
    }

    .custom-dropdown-options.top {
        top: unset;
        bottom: 100%;
        border-top: 1px solid var(--vscode-dropdown-border, var(--vscode-panel-border));
        border-bottom: none;
    }

    .custom-dropdown-option {
        color: var(--vscode-input-foreground);
        padding: 8px 12px;
        cursor: pointer;
        text-align: left;
        white-space: pre;
        display: flex;
        flex-direction: row-reverse;
        justify-content: flex-end;

        >span {
            white-space: pre;
            text-wrap: wrap;
        }

        .cdo-mock-checkbox {
            pointer-events: none;
        }

    }

    .custom-dropdown-option.dds-selected {
        background-color: var(--vscode-list-inactiveSelectionBackground) !important;
    }


    .custom-dropdown-option:hover {
        background-color: var(--vscode-list-hoverBackground);
    }

    .hidden {
        display: none !important;
    }

    :not(:has(>.custom-dropdown>.hidden)) {
        /* border: 1px solid #ccc; */
    }
}

/* #endregion */